<?php
require_once __DIR__ . '/../core/bootstrap.php';
function auth_login() { if (is_logged()) redirect('dashboard.php'); $error = ''; if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $u = authenticate_user(trim($_POST['username'] ?? ''), $_POST['password'] ?? ''); if ($u) { session_regenerate_id(true); $_SESSION['user'] = ['id' => $u['id'], 'username' => $u['username'], 'full_name' => $u['full_name'], 'role' => $u['role'], 'email' => $u['email'], 'avatar' => $u['avatar'], 'language' => $u['language'], 'theme' => $u['theme'], 'is_asesor' => $u['is_asesor']]; $_SESSION['lang'] = $u['language'] ?: 'es'; audit('login', 'users', (int)$u['id']); redirect('dashboard.php'); } else { $error = t('invalid_credentials'); } } return $error; }
function auth_logout() { audit('logout'); $_SESSION = []; session_destroy(); redirect('login.php'); }
function profile_update() { require_login(); verify_csrf(); $u = current_user(); $um = new UserModel(); $full_name = trim($_POST['full_name'] ?? ''); $email = trim($_POST['email'] ?? ''); $avatar_url = trim($_POST['avatar_url'] ?? ''); $avatar_file = $_FILES['avatar_file'] ?? null; $data = ['full_name' => $full_name ?: null, 'email' => $email ?: null]; if (!empty($avatar_url)) { $data['avatar'] = $avatar_url; } elseif ($avatar_file && ($avatar_file['error'] ?? null) === UPLOAD_ERR_OK) { $ext = strtolower(pathinfo($avatar_file['name'], PATHINFO_EXTENSION)); if (in_array($ext, ['jpg', 'jpeg', 'png', 'webp'])) { $dir = dirname(__DIR__) . '/assets/avatars/'; if (!is_dir($dir)) mkdir($dir, 0755, true); $new_name = 'avatar_' . $u['id'] . '.' . $ext; if (move_uploaded_file($avatar_file['tmp_name'], $dir . $new_name)) { $data['avatar'] = 'assets/avatars/' . $new_name; } } else { flash('error', 'Formato de imagen no válido (use JPG, PNG o WEBP).'); } } if (!empty($data)) { $um->update_profile($u['id'], $data); foreach ($data as $k => $v) $_SESSION['user'][$k] = $v; } $cur = $_POST['current_password'] ?? ''; $new = $_POST['new_password'] ?? ''; if ($cur !== '' && $new !== '') { $me = $um->find($u['id']); if (verify_password($cur, $me['password_hash'])) { if (strlen($new) >= 6) { $um->change_password($u['id'], create_password_hash($new)); flash('success', 'Perfil y contraseña actualizados correctamente.'); } else { flash('error', 'La nueva contraseña debe tener al menos 6 caracteres.'); } } else { flash('error', 'La contraseña actual es incorrecta.'); } } else { flash('success', 'Perfil actualizado correctamente.'); } redirect('profile.php'); }
